# REVIEWED
# problem P-65e58b (generated by fable): For $N\in\mathbb N$ let $r_3(N)$ denote the largest size of a set $A\subseteq[N]=\{1,\dots,N\}$ containing no non-trivial $3$-term arithmetic progression, i.e. no $x,x+d,x+2d\in A$ with $d\neq0$. Behrend's construction gives $r_3(N)\ge N\exp\big(-(c_B+o(1))\sqrt{\log N}\big)$ with $c_B=2\sqrt{2\log 
# finite_form: Find a set $A\subseteq\{1,2,\dots,20000\}$ with $|A|\ge1300$ containing no three distinct elements $x<y<z$ with $x+z=2y$. (For comparison: the digit construction with base-$3$ digits in $\{0,1\}$ gives about $520$ elements, the product of exact extremal sets for $[123]$ and $[81]$ gives $32\cdot24=7
# candidate_format: A JSON array of at least 1300 distinct integers, each between 1 and 20000 inclusive (order irrelevant).

def check(candidate) -> bool:
    try:
        N = 20000
        M = 1300
        if not isinstance(candidate, list) or len(candidate) < M:
            return False
        s = set()
        for v in candidate:
            if isinstance(v, bool) or not isinstance(v, int):
                return False
            if v < 1 or v > N or v in s:
                return False
            s.add(v)
        if len(s) < M:
            return False
        bits = 0
        pe = 0  # bit k set iff 2k in A
        po = 0  # bit k set iff 2k+1 in A
        for v in s:
            bits |= 1 << v
            if v % 2 == 0:
                pe |= 1 << (v // 2)
            else:
                po |= 1 << ((v - 1) // 2)
        # For each x in A, the set of y with 2y - x in A and 2y - x == x (mod 2)
        # is (pe << x/2) if x even, (po << (x+1)/2) if x odd.
        # A nontrivial 3-AP exists iff some such y != x lies in A.
        for x in s:
            if x % 2 == 0:
                mask = pe << (x // 2)
            else:
                mask = po << ((x + 1) // 2)
            hit = mask & bits
            hit &= ~(1 << x)
            if hit:
                return False
        return True
    except Exception:
        return False
